25	export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
26	  const user = await requireUser().catch(() => null);
27	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
28	  const { id } = await params;
29	
30	  const { count } = await db.project.deleteMany({ where: { id, userId: user.id } });
31	  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
32	  return Response.json({ ok: true });
33	}
