1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { scanForSecrets } from "@/lib/secret-scan";
4	import { checkPublishRateLimit } from "@/lib/rate-limit";
5	
6	export const dynamic = "force-dynamic";
7	
8	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
9	
10	// Publishing snapshots the draft tree onto the published tree. Deliberately
11	// NOT deploying to real Nxeon hosting infra in Phase 1 — that provisioner is
12	// still gated (see the Nxeon shared-hosting security review), so *.kodely.site
13	// is served straight out of this app from the published rows.
14	//
15	// The *.kodely.site wildcard's nginx block only routes to the PROD app
16	// (port 3000) — there is no separate wildcard for staging. A project
17	// published from staging would otherwise return a *.kodely.site URL that
18	// resolves through prod's app against prod's database, where the slug
19	// doesn't exist. Deriving the mode from the request's own Host header (never
20	// touches DNS, nginx, or .env) means staging always gets a URL that resolves
21	// against itself.
22	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
23	  const user = await requireUser().catch(() => null);
24	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
25	  const { id } = await params;
26	
27	  const project = await db.project.findFirst({
28	    where: { id, userId: user.id },
29	    include: {
30	      files: { where: { published: false, kind: "build" } },
31	    },
32	  });
33	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
34	  if (project.files.length === 0) {
35	    return Response.json({ error: "Nothing to publish yet — generate a site first." }, { status: 400 });
36	  }
37	
38	  // Only gate genuinely new subdomains — republishing an already-live project
39	  // isn't the spam-farming vector this protects against.
40	  if (!project.publishedAt) {
41	    const rateLimit = await checkPublishRateLimit(user.id);
42	    if (!rateLimit.allowed) {
43	      return Response.json(
44	        { error: "You've published a lot of new sites today — try again tomorrow." },
45	        { status: 429, headers: { "Retry-After": String(rateLimit.retryAfterSeconds) } },
46	      );
47	    }
48	  }
49	
50	  // Scan both the compiled output (what's actually served) and the source
51	  // (a comment or string that got stripped by the build can still leak if
52	  // someone reads it another way) — belt and suspenders, cheap either way.
53	  const sourceFiles = await db.projectFile.findMany({
54	    where: { projectId: id, published: false, kind: "source" },
55	  });
56	  const leaks = scanForSecrets(
57	    [...project.files, ...sourceFiles].map((f) => ({ path: f.path, content: f.content })),
58	  );
59	  if (leaks.length > 0) {
60	    const { path, kind } = leaks[0];
61	    return Response.json(
62	      { error: `Publishing blocked: found what looks like a real secret in ${path} (${kind}). Remove it and try again.` },
63	      { status: 400 },
64	    );
65	  }
66	
67	  await db.$transaction([
68	    db.projectFile.deleteMany({ where: { projectId: id, published: true, kind: "build" } }),
69	    db.projectFile.createMany({
70	      data: project.files.map((f) => ({
71	        projectId: id,
72	        path: f.path,
73	        content: f.content,
74	        published: true,
75	        kind: "build",
76	      })),
77	    }),
78	    db.project.update({ where: { id }, data: { publishedAt: new Date() } }),
79	  ]);
80	
81	  const host = req.headers.get("host") ?? "";
82	  const url = host.includes("staging")
83	    ? `https://${host}/api/site/${project.slug}`
84	    : `https://${project.slug}.${SITES_BASE}`;
85	
86	  return Response.json({ url });
87	}
