3	import { useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
6	
7	type Message = { role: string; content: string };
8	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
9	
10	type Props = {
11	  projectId: string;
12	  projectName: string;
13	  slug: string;
14	  published: boolean;
15	  initialFiles: Record<string, string>;
16	  initialMessages: Message[];
17	  initialBalance: number;
18	};
19	
20	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
21	
22	// Mirrors the publish route's own Host-based derivation (see the comment
23	// there) so the header's "live site" link always matches what publish
24	// actually returned, on staging or prod, without hardcoding either.
25	function liveSiteUrl(slug: string): string {
26	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
27	  const host = window.location.host;
28	  return host.includes("staging")
29	    ? `${window.location.origin}/api/site/${slug}`
30	    : `https://${slug}.${SITES_BASE}`;
31	}
32	
33	export default function Editor(props: Props) {
34	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
35	  const [files, setFiles] = useState(props.initialFiles);
36	  const [prompt, setPrompt] = useState("");
37	  const [busy, setBusy] = useState(false);
38	  const [status, setStatus] = useState<string | null>(null);
39	  const [error, setError] = useState<string | null>(null);
40	  const [balance, setBalance] = useState(props.initialBalance);
41	  const [previewNonce, setPreviewNonce] = useState(0);
42	  const [published, setPublished] = useState(props.published);
43	  const [publishing, setPublishing] = useState(false);
44	  const [view, setView] = useState<"preview" | "code" | "history">("preview");
45	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
46	  const [restoring, setRestoring] = useState<string | null>(null);
47	  const [activeFile, setActiveFile] = useState<string | null>(null);
48	  const streamingReply = useRef("");
49	
50	  async function openHistory() {
51	    setView("history");
52	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
53	    const body = await res.json();
54	    setBuilds(body.builds ?? []);
55	  }
56	
57	  async function restore(buildId: string) {
58	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
59	    setRestoring(buildId);
60	    setError(null);
61	    try {
62	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
63	        method: "POST",
64	      });
65	      const body = await res.json();
66	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
67	      const res2 = await fetch(`/api/projects/${props.projectId}`);
68	      const body2 = await res2.json();
69	      const nextFiles: Record<string, string> = Object.fromEntries(
70	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
71	      );
72	      setFiles(nextFiles);
73	      setPreviewNonce((n) => n + 1);
74	      setView("preview");
75	    } catch (err) {
76	      setError(err instanceof Error ? err.message : "Restore failed.");
77	    } finally {
78	      setRestoring(null);
79	    }
80	  }
81	
82	  // The foundation means source files are never empty — "first build" means
83	  // no chat history yet, matching the same signal the generate route uses.
84	  const isFirstBuild = messages.length === 0;
85	
86	  // If the visitor typed a prompt on the homepage before hitting the auth
87	  // wall, that prompt survives login/signup in sessionStorage — fire it
88	  // automatically the moment they land in their new project, instead of
89	  // making them retype what they already told us.
90	  useEffect(() => {
91	    if (!isFirstBuild) return;
92	    let pending: string | null = null;
93	    let pendingImage: string | null = null;
94	    try {
95	      pending = sessionStorage.getItem(PENDING_PROMPT_KEY);
96	      pendingImage = sessionStorage.getItem(PENDING_PROMPT_IMAGE_KEY);
97	    } catch {}
98	    if (!pending) return;
99	    try {
100	      sessionStorage.removeItem(PENDING_PROMPT_KEY);
101	      sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
102	    } catch {}
103	    send(pending, pendingImage ?? undefined);
104	    // Runs once on mount only — send() is intentionally not a dependency.
105	    // eslint-disable-next-line react-hooks/exhaustive-deps
106	  }, []);
107	
108	  async function send(overrideText?: string, image?: string) {
109	    const text = (overrideText ?? prompt).trim();
110	    if (!text || busy) return;
111	    if (balance <= 0) {
112	      setError("You're out of credits. Top up to keep building.");
113	      return;
114	    }
115	
116	    setBusy(true);
117	    setError(null);
118	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
119	    setMessages((m) => [...m, { role: "user", content: text }]);
120	    setPrompt("");
121	    streamingReply.current = "";
122	
123	    try {
124	      const res = await fetch("/api/generate", {
125	        method: "POST",
126	        headers: { "Content-Type": "application/json" },
127	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
128	      });
129	
130	      if (!res.ok || !res.body) {
131	        const body = await res.json().catch(() => ({}));
132	        throw new Error(body?.error ?? "The build failed to start.");
133	      }
134	
135	      const reader = res.body.getReader();
136	      const decoder = new TextDecoder();
137	      let buffer = "";
138	      let touchedFiles = false;
139	
140	      while (true) {
141	        const { done, value } = await reader.read();
142	        if (done) break;
143	        buffer += decoder.decode(value, { stream: true });
144	
145	        const parts = buffer.split("\n\n");
146	        buffer = parts.pop() ?? "";
147	
148	        for (const part of parts) {
149	          if (!part.startsWith("data: ")) continue;
150	          const event = JSON.parse(part.slice(6));
151	
152	          if (event.type === "text") {
153	            streamingReply.current += event.text;
154	          } else if (event.type === "file") {
155	            touchedFiles = true;
156	            setStatus(`${event.action === "write" ? "Writing" : "Removing"} ${event.path}`);
157	          } else if (event.type === "done") {
158	            setBalance(event.remaining);
159	            setStatus(null);
160	          } else if (event.type === "error") {
161	            throw new Error(event.message);
162	          }
163	        }
164	      }
165	
166	      if (streamingReply.current.trim()) {
167	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
168	      }
169	      if (touchedFiles) {
170	        const res2 = await fetch(`/api/projects/${props.projectId}`);
171	        const body = await res2.json();
172	        const nextFiles: Record<string, string> = Object.fromEntries(
173	          (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
174	        );
175	        setFiles(nextFiles);
176	        setPreviewNonce((n) => n + 1);
177	      }
178	    } catch (err) {
179	      setError(err instanceof Error ? err.message : "Something went wrong.");
180	    } finally {
181	      setBusy(false);
182	      setStatus(null);
183	    }
184	  }
185	
186	  async function publish() {
187	    setPublishing(true);
188	    setError(null);
189	    try {
190	      const res = await fetch(`/api/projects/${props.projectId}/publish`, { method: "POST" });
191	      const body = await res.json();
192	      if (!res.ok) throw new Error(body?.error ?? "Publish failed.");
193	      setPublished(true);
194	      window.open(body.url, "_blank");
195	    } catch (err) {
196	      setError(err instanceof Error ? err.message : "Publish failed.");
197	    } finally {
198	      setPublishing(false);
199	    }
200	  }
201	
202	  return (
203	    <div className="flex h-screen flex-col">
204	      <header className="flex items-center justify-between border-b border-black/10 px-4 py-2.5 dark:border-white/10">
205	        <div className="flex items-center gap-3">
206	          <Link href="/dashboard" className="text-sm text-black/50 hover:text-black dark:text-white/50 dark:hover:text-white">
207	            ←
208	          </Link>
209	          <span className="text-sm font-medium">{props.projectName}</span>
210	        </div>
211	        <div className="flex items-center gap-3">
212	          <div className="flex items-center gap-1 rounded-lg border border-black/10 p-0.5 text-xs dark:border-white/10">
213	            <button
214	              onClick={() => setView("preview")}
215	              className={`rounded-md px-2 py-1 ${view === "preview" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
216	            >
217	              Preview
218	            </button>
219	            <button
220	              onClick={() => {
221	                setView("code");
222	                setActiveFile((f) => f ?? Object.keys(files)[0] ?? null);
223	              }}
224	              className={`rounded-md px-2 py-1 ${view === "code" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
225	              disabled={isFirstBuild}
226	            >
227	              Code
228	            </button>
229	            <button
230	              onClick={openHistory}
231	              className={`rounded-md px-2 py-1 ${view === "history" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
232	              disabled={isFirstBuild}
233	            >
234	              History
235	            </button>
236	          </div>
237	          <span className="text-xs text-black/50 dark:text-white/50">{balance} credits</span>
238	          {published && (
239	            <a
240	              href={liveSiteUrl(props.slug)}
241	              target="_blank"
242	              className="text-xs text-black/50 underline hover:text-black dark:text-white/50 dark:hover:text-white"
243	            >
244	              live site ↗
245	            </a>
246	          )}
247	          <button
248	            onClick={publish}
249	            disabled={publishing || isFirstBuild}
250	            className="rounded-lg bg-black px-3 py-1.5 text-xs font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black"
251	          >
252	            {publishing ? "Publishing…" : published ? "Republish" : "Publish"}
253	          </button>
254	        </div>
255	      </header>
256	
257	      <div className="flex min-h-0 flex-1">
258	        <div className="flex w-96 shrink-0 flex-col border-r border-black/10 dark:border-white/10">
259	          <div className="flex-1 space-y-3 overflow-y-auto p-4">
260	            {messages.length === 0 && (
261	              <p className="text-sm text-black/50 dark:text-white/50">
262	                Describe the site you want. Be specific — audience, purpose, tone.
263	              </p>
264	            )}
265	            {messages.map((m, i) => (
266	              <div key={i} className={m.role === "user" ? "text-sm" : "text-sm text-black/70 dark:text-white/70"}>
267	                <div className="mb-0.5 text-xs font-medium text-black/40 dark:text-white/40">
268	                  {m.role === "user" ? "You" : "Kodely"}
269	                </div>
270	                <div className="whitespace-pre-wrap">{m.content}</div>
271	              </div>
272	            ))}
273	            {status && <div className="text-xs text-black/40 dark:text-white/40">{status}</div>}
274	            {error && <div className="text-xs text-red-600">{error}</div>}
275	          </div>
276	          <div className="border-t border-black/10 p-3 dark:border-white/10">
277	            <textarea
278	              value={prompt}
279	              onChange={(e) => setPrompt(e.target.value)}
280	              onKeyDown={(e) => {
281	                if (e.key === "Enter" && !e.shiftKey) {
282	                  e.preventDefault();
283	                  send();
284	                }
285	              }}
286	              placeholder={isFirstBuild ? "e.g. A landing page for a coffee roastery in Portland" : "Describe a change…"}
287	              rows={3}
288	              className="w-full resize-none rounded-lg border border-black/15 bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40"
289	            />
290	            <button
291	              onClick={() => send()}
292	              disabled={busy || !prompt.trim()}
293	              className="mt-2 w-full rounded-lg bg-black px-3 py-2 text-sm font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black"
294	            >
295	              {busy ? "Building…" : isFirstBuild ? "Build site" : "Apply change"}
296	            </button>
297	          </div>
298	        </div>
299	
300	        <div className="min-w-0 flex-1 bg-black/[0.02] dark:bg-white/[0.02]">
301	          {view === "preview" && (
302	            <iframe
303	              key={previewNonce}
304	              src={`/api/preview/${props.projectId}?v=${previewNonce}`}
305	              sandbox="allow-scripts allow-forms"
306	              className="h-full w-full border-0 bg-white"
307	              title="Live preview"
308	            />
309	          )}
310	
311	          {view === "code" && (
312	            <div className="flex h-full">
313	              <div className="w-48 shrink-0 overflow-y-auto border-r border-black/10 p-2 dark:border-white/10">
314	                {Object.keys(files).map((path) => (
315	                  <button
316	                    key={path}
317	                    onClick={() => setActiveFile(path)}
318	                    className={`block w-full truncate rounded-md px-2 py-1.5 text-left text-xs ${
319	                      activeFile === path
320	                        ? "bg-black/10 font-medium dark:bg-white/10"
321	                        : "text-black/60 hover:bg-black/5 dark:text-white/60 dark:hover:bg-white/5"
322	                    }`}
323	                  >
324	                    {path}
325	                  </button>
326	                ))}
327	              </div>
328	              <div className="min-w-0 flex-1 overflow-auto">
329	                {activeFile && files[activeFile] !== undefined ? (
330	                  <div className="relative">
331	                    <button
332	                      onClick={() => navigator.clipboard.writeText(files[activeFile])}
333	                      className="absolute right-3 top-3 rounded-md border border-black/15 bg-white px-2 py-1 text-xs dark:border-white/15 dark:bg-black"
334	                    >
335	                      Copy
336	                    </button>
337	                    <pre className="p-4 text-xs leading-relaxed">
338	                      <code>{files[activeFile]}</code>
339	                    </pre>
340	                  </div>
341	                ) : (
342	                  <p className="p-4 text-sm text-black/50 dark:text-white/50">Select a file.</p>
343	                )}
344	              </div>
345	            </div>
346	          )}
347	
348	          {view === "history" && (
349	            <div className="h-full overflow-y-auto p-4">
350	              {builds === null ? (
351	                <p className="text-sm text-black/50 dark:text-white/50">Loading…</p>
352	              ) : builds.length === 0 ? (
353	                <p className="text-sm text-black/50 dark:text-white/50">No checkpoints yet.</p>
354	              ) : (
355	                <ul className="space-y-2">
356	                  {builds.map((b) => (
